// icons.h - every bitmap, in one place.
//
// Named <what>_<size>, e.g. icon_rain_48 / icon_rain_96, so a call site can't
// grab the wrong one. Weather icons are ordered to match the WxIcon enum.
//
// Each array has a static_assert on its size. A bitmap must be exactly
// ceil(w/8)*h bytes, or drawBitmap() reads past the end of it.
//
// Include from screens.cpp only. These are `static`, so every extra include
// puts another copy of every array in flash.

#pragma once
#include <Arduino.h> // for PROGMEM
#include <stddef.h>

#define ICON_BYTES(w, h) ((((w) + 7) / 8) * (h))

// INTERFACE -----------------------------------------------------------------------------------------
